-- Trusted server PIN sessions use the private service credential after verification.
create or replace function private.is_admin() returns boolean language sql stable security definer set search_path='' as $$
 select coalesce((select auth.jwt()->>'role')='service_role',false) or (auth.uid() is not null and exists(select 1 from public.user_roles where user_id=auth.uid() and role='admin'))
$$;
alter table public.product_prices add column approved_via text not null default 'account' check(approved_via in ('account','owner_pin'));
do $$ declare c record; begin for c in select conname from pg_constraint where conrelid='public.product_prices'::regclass and contype='c' and pg_get_constraintdef(oid) like '%approved_by%' loop execute format('alter table public.product_prices drop constraint %I',c.conname); end loop; end $$;
alter table public.product_prices add constraint price_approval_required check(not verified or (source_reference is not null and (approved_by is not null or approved_via='owner_pin')));
-- Owner workspace: live content, stock, appointments, staff invitations and audit history.
alter table public.products add column compare_at_pence bigint check(compare_at_pence >= 0),
 add column badge text not null default '', add column tags text[] not null default '{}',
 add column stock_packs integer not null default 0 check(stock_packs >= 0),
 add column reorder_level integer not null default 5 check(reorder_level >= 0),
 add column warehouse_location text not null default '', add column supplier text not null default '',
 add column stock_confirmed boolean not null default false;
alter table public.retailer_applications add column review_notes text not null default '';
create table public.site_content (
 id uuid primary key default gen_random_uuid(), key text not null unique,
 draft jsonb not null default '{}', published jsonb, published_at timestamptz,
 created_at timestamptz not null default now(), updated_at timestamptz not null default now()
);
create table public.staff_invitations (
 id uuid primary key default gen_random_uuid(), email text not null unique check(email=lower(email)),
 access text not null check(access in ('owner','developer')), enabled boolean not null default true,
 claimed_by uuid references auth.users(id), invited_by uuid references auth.users(id),
 created_at timestamptz not null default now(), updated_at timestamptz not null default now()
);
create table public.staff_members (
 user_id uuid primary key references auth.users(id), invitation_id uuid not null references public.staff_invitations(id),
 access text not null check(access in ('owner','developer')), enabled boolean not null default true,
 created_at timestamptz not null default now(), updated_at timestamptz not null default now()
);
create table public.work_orders (
 id uuid primary key default gen_random_uuid(), reference text not null unique default ('JOB-'||upper(substr(replace(gen_random_uuid()::text,'-',''),1,10))),
 contact_name text not null, email text not null default '', phone text not null default '',
 address text not null default '', postcode text not null default '',
 kind text not null default 'delivery' check(kind in ('delivery','measure','fitting','collection')),
 status text not null default 'scheduled' check(status in ('scheduled','confirmed','in_progress','completed','cancelled')),
 scheduled_at timestamptz, assignee text not null default '', notes text not null default '',
 created_at timestamptz not null default now(), updated_at timestamptz not null default now()
);
create table public.audit_log (
 id uuid primary key default gen_random_uuid(), actor_id uuid references auth.users(id),
 entity text not null, record_id text, action text not null,
 changes jsonb not null default '{}', created_at timestamptz not null default now()
);
do $$ declare t text; begin
 foreach t in array array['site_content','staff_invitations','staff_members','work_orders'] loop
 execute format('alter table public.%I enable row level security',t);
 execute format('grant select,insert,update,delete on public.%I to authenticated',t);
 execute format('create policy admin_access on public.%I for all to authenticated using ((select private.is_admin())) with check ((select private.is_admin()))',t);
 execute format('create trigger updated_at before update on public.%I for each row execute function private.touch_updated_at()',t);
 end loop;
end $$;
alter table public.audit_log enable row level security;
grant select on public.audit_log to authenticated;
create policy admin_read on public.audit_log for select to authenticated using ((select private.is_admin()));
create index audit_log_date_idx on public.audit_log(created_at desc);
create index staff_invitations_claim_idx on public.staff_invitations(claimed_by);
create index staff_members_invitation_idx on public.staff_members(invitation_id);
create index work_orders_schedule_idx on public.work_orders(scheduled_at,status);
create policy own_staff_membership on public.staff_members for select to authenticated using(user_id=(select auth.uid()));
grant select(id,key,published,published_at) on public.site_content to anon;
create policy published_site_content on public.site_content for select to anon using(published is not null);
-- Authenticated customers must not receive the draft column via a permissive policy.
create view public.published_site_content with (security_invoker=true) as select id,key,published,published_at from public.site_content where published is not null;
grant select on public.published_site_content to anon,authenticated;
create policy authenticated_content on public.site_content for select to authenticated using(published is not null);
-- Remove full authenticated SELECT: owners read drafts through an owner-only RPC.
revoke select on public.site_content from authenticated;
grant select(id,key,published,published_at) on public.site_content to authenticated;

create function public.owner_content() returns setof public.site_content language plpgsql security definer set search_path='' as $$
begin if not private.is_admin() then raise exception 'Owner access required' using errcode='42501'; end if;
return query select * from public.site_content order by key; end $$;
revoke all on function public.owner_content() from public;
grant execute on function public.owner_content() to authenticated;

create function private.audit_owner_change() returns trigger language plpgsql security definer set search_path='' as $$
declare old_row jsonb; new_row jsonb; begin
 if tg_op <> 'INSERT' then old_row=to_jsonb(old); end if;
 if tg_op <> 'DELETE' then new_row=to_jsonb(new); end if;
 insert into public.audit_log(actor_id,entity,record_id,action,changes)
 values(auth.uid(),tg_table_name,coalesce(new_row->>'id',new_row->>'user_id',old_row->>'id',old_row->>'user_id'),tg_op,
 jsonb_build_object('before',old_row,'after',new_row));
 if tg_op='DELETE' then return old; end if; return new; end $$;
revoke all on function private.audit_owner_change() from public;
do $$ declare t text; begin
 foreach t in array array['products','product_prices','product_images','categories','collections','site_content','retailer_applications','retailer_profiles','company_settings','work_orders','staff_invitations','staff_members','enquiries','sample_requests','quotations','invoices','support_tickets'] loop
 execute format('create trigger owner_audit after insert or update or delete on public.%I for each row execute function private.audit_owner_change()',t);
 end loop;
end $$;

-- Invitations are issued by an owner; verified email possession is required to claim.
create function public.claim_staff_access() returns text language plpgsql security definer set search_path='' as $$
declare invitation public.staff_invitations; account_email text; begin
 select lower(email) into account_email from auth.users where id=auth.uid() and email_confirmed_at is not null;
 if account_email is null then raise exception 'Verify your email first' using errcode='42501'; end if;
 select * into invitation from public.staff_invitations where email=account_email and enabled for update;
 if not found then raise exception 'No staff invitation for this account' using errcode='42501'; end if;
 if invitation.claimed_by is not null and invitation.claimed_by <> auth.uid() then raise exception 'Invitation already used' using errcode='42501'; end if;
 insert into public.staff_members(user_id,invitation_id,access) values(auth.uid(),invitation.id,invitation.access)
 on conflict(user_id) do update set access=excluded.access,enabled=true,invitation_id=excluded.invitation_id;
 if invitation.access='owner' then
 insert into public.user_roles(user_id,role) values(auth.uid(),'admin') on conflict(user_id) do update set role='admin'; end if;
 update public.staff_invitations set claimed_by=auth.uid() where id=invitation.id;
 return invitation.access; end $$;
revoke all on function public.claim_staff_access() from public;
grant execute on function public.claim_staff_access() to authenticated;

create function public.review_retailer(application uuid, decision text, notes text default '') returns void language plpgsql security definer set search_path='' as $$
declare app public.retailer_applications; begin
 if not private.is_admin() then raise exception 'Owner access required' using errcode='42501'; end if;
 if decision not in ('approved','rejected','suspended') then raise exception 'Invalid decision'; end if;
 select * into app from public.retailer_applications where id=application for update;
 if not found or app.user_id is null then raise exception 'Verified retailer account required'; end if;
 if exists(select 1 from public.user_roles where user_id=app.user_id and role='admin') then raise exception 'Cannot change an owner account'; end if;
 if decision='approved' then
 if not exists(select 1 from auth.users where id=app.user_id and email_confirmed_at is not null) then raise exception 'Retailer email is not verified'; end if;
 insert into public.retailer_profiles(user_id,application_id,business_name,status) values(app.user_id,app.id,app.business_name,'approved')
 on conflict(user_id) do update set status='approved',business_name=excluded.business_name,application_id=excluded.application_id;
 insert into public.user_roles(user_id,role) values(app.user_id,'retailer') on conflict(user_id) do update set role='retailer';
 else
 update public.retailer_profiles set status='suspended' where user_id=app.user_id;
 update public.user_roles set role='customer' where user_id=app.user_id and role='retailer';
 end if;
 update public.retailer_applications set status=case when decision='suspended' then status else decision end,
 review_notes=left(notes,4000),reviewed_at=now(),reviewed_by=auth.uid() where id=application;
 end $$;
revoke all on function public.review_retailer(uuid,text,text) from public;
grant execute on function public.review_retailer(uuid,text,text) to authenticated;

-- Atomic product, media and verified selling-price changes.
create function public.save_owner_product(payload jsonb) returns uuid language plpgsql security invoker set search_path='' as $$
declare pid uuid; item jsonb; position_no integer=0; begin
 if not private.is_admin() then raise exception 'Owner access required' using errcode='42501'; end if;
 pid=coalesce(nullif(payload->>'id','')::uuid,gen_random_uuid());
 insert into public.products(id,slug,name,category_id,brand,sku,description,colour,material,finish,thickness,dimensions,wear_layer,installation,warranty,pack_coverage,availability,status,badge,tags,compare_at_pence,stock_packs,reorder_level,warehouse_location,supplier,stock_confirmed)
 values(pid,payload->>'slug',payload->>'name',(payload->>'category_id')::uuid,payload->>'brand',nullif(payload->>'sku',''),payload->>'description',payload->>'colour',payload->>'material',payload->>'finish',payload->>'thickness',payload->>'dimensions',payload->>'wear_layer',payload->>'installation',payload->>'warranty',(payload->>'pack_coverage')::numeric,payload->>'availability',payload->>'status',payload->>'badge',array(select jsonb_array_elements_text(payload->'tags')),(payload->>'compare_at_pence')::bigint,(payload->>'stock_packs')::integer,(payload->>'reorder_level')::integer,payload->>'warehouse_location',payload->>'supplier',(payload->>'stock_confirmed')::boolean)
 on conflict(id) do update set slug=excluded.slug,name=excluded.name,category_id=excluded.category_id,brand=excluded.brand,sku=excluded.sku,description=excluded.description,colour=excluded.colour,material=excluded.material,finish=excluded.finish,thickness=excluded.thickness,dimensions=excluded.dimensions,wear_layer=excluded.wear_layer,installation=excluded.installation,warranty=excluded.warranty,pack_coverage=excluded.pack_coverage,availability=excluded.availability,status=excluded.status,badge=excluded.badge,tags=excluded.tags,compare_at_pence=excluded.compare_at_pence,stock_packs=excluded.stock_packs,reorder_level=excluded.reorder_level,warehouse_location=excluded.warehouse_location,supplier=excluded.supplier,stock_confirmed=excluded.stock_confirmed;
 update public.product_prices set active=false where product_id=pid and active and variant_id is null and unit='sqm';
 insert into public.product_prices(product_id,amount_pence,unit,vat_included,vat_basis_points,verified,approved_by,source_reference,approved_via)
 values(pid,(payload->>'price_pence')::bigint,'sqm',true,(payload->>'vat_basis_points')::integer,true,auth.uid(),'Owner product editor',case when auth.uid() is null then 'owner_pin' else 'account' end);
 delete from public.product_images where product_id=pid;
 for item in select value from jsonb_array_elements(payload->'images') loop
 insert into public.product_images(product_id,url,alt,position) values(pid,item->>'url',item->>'alt',position_no);
 position_no=position_no+1;
 end loop;
 return pid; end $$;
revoke all on function public.save_owner_product(jsonb) from public;
grant execute on function public.save_owner_product(jsonb) to authenticated;

insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types)
 values('storefront-media','storefront-media',true,10485760,array['image/jpeg','image/png','image/webp','image/avif','video/mp4']);
create policy owner_media_insert on storage.objects for insert to authenticated with check(bucket_id='storefront-media' and (select private.is_admin()));
create policy owner_media_select on storage.objects for select to authenticated using(bucket_id='storefront-media' and (select private.is_admin()));
create policy owner_media_update on storage.objects for update to authenticated using(bucket_id='storefront-media' and (select private.is_admin())) with check(bucket_id='storefront-media' and (select private.is_admin()));
create policy owner_media_delete on storage.objects for delete to authenticated using(bucket_id='storefront-media' and (select private.is_admin()));

create function private.sync_staff_invitation() returns trigger language plpgsql security definer set search_path='' as $$
begin update public.staff_members set enabled=new.enabled where invitation_id=new.id; return new; end $$;
revoke all on function private.sync_staff_invitation() from public;
create trigger staff_invitation_access after update of enabled on public.staff_invitations for each row execute function private.sync_staff_invitation();

create table public.manufacturer_ranges (
 id uuid primary key default gen_random_uuid(), slug text not null unique, name text not null,
 brand text not null default 'UNIQ FLOORS', collection text not null default '',
 category text not null check(category in ('lvt','carpet')), image text not null default '',
 variants jsonb not null default '[]' check(jsonb_typeof(variants)='array'),
 published boolean not null default false,
 created_at timestamptz not null default now(),updated_at timestamptz not null default now()
);
alter table public.manufacturer_ranges enable row level security;
grant select on public.manufacturer_ranges to anon;
grant select,insert,update,delete on public.manufacturer_ranges to authenticated;
create policy public_ranges on public.manufacturer_ranges for select to anon,authenticated using(published);
create policy admin_access on public.manufacturer_ranges for all to authenticated using((select private.is_admin())) with check((select private.is_admin()));
create trigger updated_at before update on public.manufacturer_ranges for each row execute function private.touch_updated_at();
create trigger owner_audit after insert or update or delete on public.manufacturer_ranges for each row execute function private.audit_owner_change();

