create function public.create_owner_quote(payload jsonb) returns uuid language plpgsql security invoker set search_path='' as $$
declare qid uuid; item jsonb; begin
 if not private.is_admin() then raise exception 'Owner access required' using errcode='42501'; end if;
 insert into public.quotations(customer_id,valid_until,discount_pence,delivery_pence,vat_basis_points,notes)
 values((payload->>'customer_id')::uuid,(payload->>'valid_until')::date,(payload->>'discount_pence')::bigint,(payload->>'delivery_pence')::bigint,(payload->>'vat_basis_points')::integer,payload->>'notes') returning id into qid;
 for item in select value from jsonb_array_elements(payload->'items') loop
 insert into public.quotation_items(quotation_id,description,quantity,unit,unit_price_pence) values(qid,item->>'description',(item->>'quantity')::numeric,item->>'unit',(item->>'unit_price_pence')::bigint);
 end loop; return qid; end $$;
revoke all on function public.create_owner_quote(jsonb) from public;
grant execute on function public.create_owner_quote(jsonb) to authenticated;
create unique index one_invoice_per_quote on public.invoices(quotation_id) where quotation_id is not null;
create function public.invoice_from_quote(quote_id uuid) returns uuid language plpgsql security invoker set search_path='' as $$
declare q public.quotations; iid uuid; begin
 if not private.is_admin() then raise exception 'Owner access required' using errcode='42501'; end if;
 select * into q from public.quotations where id=quote_id for update;
 if not found then raise exception 'Quotation not found'; end if;
 select id into iid from public.invoices where quotation_id=quote_id;
 if iid is not null then return iid; end if;
 insert into public.invoices(quotation_id,customer_id,user_id,invoice_date,due_date,discount_pence,delivery_pence,vat_basis_points,notes,company_snapshot,customer_snapshot,payment_instructions)
 values(q.id,q.customer_id,q.user_id,current_date,current_date+30,q.discount_pence,q.delivery_pence,q.vat_basis_points,q.notes,(select to_jsonb(s) from public.company_settings s where id=true),(select to_jsonb(c) from public.customers c where id=q.customer_id),(select coalesce(payment_instructions,'') from public.company_settings where id=true)) returning id into iid;
 insert into public.invoice_items(invoice_id,product_id,description,quantity,unit,unit_price_pence) select iid,product_id,description,quantity,unit,unit_price_pence from public.quotation_items where quotation_id=q.id;
 return iid; end $$;
revoke all on function public.invoice_from_quote(uuid) from public;
grant execute on function public.invoice_from_quote(uuid) to authenticated;

-- A global, database-backed attempt budget prevents distributed brute force of the owner PIN.
create table private.owner_pin_attempts (id boolean primary key default true check(id), attempts integer not null default 0, expires_at timestamptz not null);
alter table private.owner_pin_attempts enable row level security;
revoke all on private.owner_pin_attempts from public,anon,authenticated;
create function public.owner_pin_attempt() returns boolean language plpgsql security definer set search_path='' as $$
declare attempt private.owner_pin_attempts; begin
 insert into private.owner_pin_attempts(id,attempts,expires_at) values(true,0,now()+interval '10 minutes') on conflict(id) do nothing;
 select * into attempt from private.owner_pin_attempts where id=true for update;
 if attempt.expires_at<=now() then update private.owner_pin_attempts set attempts=1,expires_at=now()+interval '10 minutes' where id=true; return true; end if;
 if attempt.attempts>=5 then return false; end if;
 update private.owner_pin_attempts set attempts=attempts+1 where id=true; return true; end $$;
create function public.owner_pin_reset() returns void language sql security definer set search_path='' as $$ update private.owner_pin_attempts set attempts=0 where id=true $$;
revoke all on function public.owner_pin_attempt(),public.owner_pin_reset() from public,anon,authenticated;
grant execute on function public.owner_pin_attempt(),public.owner_pin_reset() to service_role;

grant usage on schema private to service_role;
grant execute on function private.is_admin() to service_role;
grant select,insert,update,delete on public.products,public.product_prices,public.product_images,public.categories,public.collections,public.site_content,public.manufacturer_ranges,public.staff_invitations,public.staff_members,public.retailer_applications,public.retailer_profiles,public.enquiries,public.enquiry_items,public.sample_requests,public.sample_request_items,public.customers,public.work_orders,public.quotations,public.quotation_items,public.invoices,public.invoice_items,public.support_tickets,public.ticket_messages,public.company_settings to service_role;
grant select on public.audit_log to service_role;
grant select on public.published_site_content to service_role;
grant execute on function public.save_owner_product(jsonb),public.owner_content(),public.review_retailer(uuid,text,text),public.create_owner_quote(jsonb),public.invoice_from_quote(uuid) to service_role;

-- Revocable server sessions: signing out invalidates the token at the database as well.
create table private.owner_sessions (token_hash text primary key check(length(token_hash)=64),expires_at timestamptz not null);
alter table private.owner_sessions enable row level security;
revoke all on private.owner_sessions from public,anon,authenticated;
create function public.owner_session(action text,session_hash text,expires timestamptz default null) returns boolean language plpgsql security definer set search_path='' as $$
begin
 if length(session_hash)<>64 or session_hash !~ '^[a-f0-9]+$' then return false; end if;
 if action='create' then
 if expires is null or expires>now()+interval '2 hours 1 minute' or expires<=now() then return false; end if;
 delete from private.owner_sessions where expires_at<now();
 insert into private.owner_sessions(token_hash,expires_at) values(session_hash,expires); return true;
 elsif action='revoke' then delete from private.owner_sessions where token_hash=session_hash;return true;
 elsif action='verify' then return exists(select 1 from private.owner_sessions where token_hash=session_hash and expires_at>now());end if;
 return false;end $$;
revoke all on function public.owner_session(text,text,timestamptz) from public,anon,authenticated;
grant execute on function public.owner_session(text,text,timestamptz) to service_role;

-- Supplier names, warehouse bins and stock records remain private.
revoke select on public.products from anon;
grant select(id,slug,name,category_id,collection_id,brand,sku,description,colour,material,finish,thickness,dimensions,wear_layer,installation,warranty,warranty_verified,pack_coverage,availability,status,source_url,verified_at,created_at,updated_at,badge,tags,compare_at_pence) on public.products to anon;
drop policy published_products on public.products;
create policy published_products on public.products for select to anon using(status='published');
-- Public contact fields are opt-in and never include payment or email-provider settings.
grant select(company_name,business_email,whatsapp_number,address,vat_number,public_contact_approved) on public.company_settings to anon;
create policy public_contacts on public.company_settings for select to anon using(public_contact_approved);
create view public.public_business_details with (security_invoker=true) as select company_name,business_email,whatsapp_number,address,vat_number from public.company_settings where public_contact_approved;
grant select on public.public_business_details to anon;
